//! TypeScript declarations of every contract type, as one module. The web console imports the
//! generated file; `tests/generated.rs` fails when it drifts (`UPDATE_GENERATED=1` rewrites it).

use ts_rs::{Config, TS};

use crate::diff::{Category, Change, Direction, SurfaceDiff};
use crate::draft::{Draft, DraftField, Evidence, Strength};
use crate::edge::{EdgeConfig, Mode, Route, Verifier};
use crate::ledger::{ActivationReason, Approver, LedgerBody, ProofMethod, Proposer, Provenance, Stage, TaintFinding};
use crate::manifest::*;
use crate::policy::{OnCallAction, ReleasePolicy, Requirement, StandingOrder};
use crate::principal::PrincipalClaims;
use crate::validate::{Refusal, RefusalCode};

/// Appends `export type …` for `T` to `out`.
pub fn push<T: TS + ?Sized + 'static>(out: &mut String, cfg: &Config) {
    out.push_str("export ");
    out.push_str(T::decl(cfg).trim_end());
    if !out.ends_with(';') {
        out.push(';');
    }
    out.push_str("\n\n");
}

pub const HEADER: &str = "// @generated by cloud-contract tests (UPDATE_GENERATED=1 cargo test -p cloud-contract). Do not edit.\n\n";
/// JSON numbers are `number` in the console; ids and timestamps stay below 2^53.
pub fn config() -> Config {
    Config::new().with_large_int("number")
}

pub fn typescript() -> String {
    let cfg = config();
    let mut out = String::from(HEADER);
    macro_rules! all {
        ($($t:ty),* $(,)?) => { $( push::<$t>(&mut out, &cfg); )* };
    }
    all!(
        Manifest,
        Source,
        Build,
        Process,
        Expose,
        Health,
        Volume,
        Domain,
        DomainMode,
        Auth,
        OidcProvider,
        Secret,
        DataClass,
        Owner,
        Contact,
        Budget,
        Degrade,
        Refusal,
        RefusalCode,
        Category,
        Direction,
        Change,
        SurfaceDiff,
        ReleasePolicy,
        Requirement,
        StandingOrder,
        OnCallAction,
        EdgeConfig,
        Route,
        Mode,
        Verifier,
        PrincipalClaims,
        Stage,
        Provenance,
        Proposer,
        ProofMethod,
        Approver,
        ActivationReason,
        TaintFinding,
        LedgerBody,
        Strength,
        Evidence,
        DraftField,
        Draft,
    );
    out
}
